-- HOW TO RUN IN CMD:
-- sqlcmd -S localhost -U sa -P YourPassword -i digital_library.sql

CREATE DATABASE DigitalLibrary;
GO
USE DigitalLibrary;
GO

-- ============================================================
-- CREATE TABLES
-- ============================================================

-- 1. Membership (must be first, Member references it)
CREATE TABLE Membership (
    Membership_ID   INT          PRIMARY KEY,
    Membership_Name VARCHAR(50)  NOT NULL,
    Annual_Fee      DECIMAL(8,2) NOT NULL,
    Discount_Pct    DECIMAL(5,2) NOT NULL,   -- e.g. 40 means 40%
    Free_Item_Limit INT          NOT NULL    -- e.g. 10 free charged items
);
GO

-- 2. Member
CREATE TABLE Member (
    Member_ID     INT          PRIMARY KEY,
    Membership_ID INT          NOT NULL,
    Name          VARCHAR(100) NOT NULL,
    Address       VARCHAR(200),
    Phone         VARCHAR(20),
    Email         VARCHAR(100),
    Join_Date     DATE,
    FOREIGN KEY (Membership_ID) REFERENCES Membership(Membership_ID)
);
GO

-- 3. Guest
CREATE TABLE Guest (
    Guest_ID   INT          PRIMARY KEY,
    Guest_Name VARCHAR(100),
    Email      VARCHAR(100),
    Visit_Date DATE
);
GO

-- 4. Access_Type
--    Is_Public=1 means guests can access
--    Is_Chargeable=1 means payment required
--    Download_Allowed=1 means can download
--    View_Only=1 means can only view
CREATE TABLE Access_Type (
    Access_Type_ID   INT          PRIMARY KEY,
    Access_Name      VARCHAR(100) NOT NULL,
    Is_Public        BIT          NOT NULL DEFAULT 0,
    Is_Chargeable    BIT          NOT NULL DEFAULT 0,
    Download_Allowed BIT          NOT NULL DEFAULT 0,
    View_Only        BIT          NOT NULL DEFAULT 0
);
GO

-- 5. Item_Type (eBook, eJournal, Journal Article, Software Tool)
CREATE TABLE Item_Type (
    Item_Type_ID INT          PRIMARY KEY,
    Type_Name    VARCHAR(50)  NOT NULL,
    Description  VARCHAR(200)
);
GO

-- 6. Digital_Item (core item table)
CREATE TABLE Digital_Item (
    Item_ID        INT          PRIMARY KEY,
    Item_Type_ID   INT          NOT NULL,
    Access_Type_ID INT          NOT NULL,
    Title          VARCHAR(200) NOT NULL,
    Publish_Date   DATE,
    Description    VARCHAR(500),
    FOREIGN KEY (Item_Type_ID)   REFERENCES Item_Type(Item_Type_ID),
    FOREIGN KEY (Access_Type_ID) REFERENCES Access_Type(Access_Type_ID)
);
GO

-- 7. Item_Membership_Price
--    Resolves M:M between Digital_Item and Membership
--    Stores different price per membership tier
--    e.g. Journal Article: Bronze=$20, Silver=$10, Gold=$5
CREATE TABLE Item_Membership_Price (
    Item_ID       INT          NOT NULL,
    Membership_ID INT          NOT NULL,
    Price         DECIMAL(8,2) NOT NULL,
    PRIMARY KEY (Item_ID, Membership_ID),
    FOREIGN KEY (Item_ID)       REFERENCES Digital_Item(Item_ID),
    FOREIGN KEY (Membership_ID) REFERENCES Membership(Membership_ID)
);
GO

-- 8. Category (self-referencing for sub-categories)
--    Parent_Category_ID = NULL means top-level category
CREATE TABLE Category (
    Category_ID        INT          PRIMARY KEY,
    Category_Name      VARCHAR(100) NOT NULL,
    Parent_Category_ID INT          NULL,
    FOREIGN KEY (Parent_Category_ID) REFERENCES Category(Category_ID)
);
GO

-- 9. Item_Category
--    Resolves M:M between Digital_Item and Category
--    One item can be in multiple categories
CREATE TABLE Item_Category (
    Item_ID     INT NOT NULL,
    Category_ID INT NOT NULL,
    PRIMARY KEY (Item_ID, Category_ID),
    FOREIGN KEY (Item_ID)     REFERENCES Digital_Item(Item_ID),
    FOREIGN KEY (Category_ID) REFERENCES Category(Category_ID)
);
GO

-- 10. Access_Record
--     Tracks which member accessed which item
--     Also stores charged amount and savings for reports
CREATE TABLE Access_Record (
    Access_ID      INT          PRIMARY KEY,
    Member_ID      INT          NOT NULL,
    Item_ID        INT          NOT NULL,
    Access_Type_ID INT          NOT NULL,
    Access_Date    DATE         NOT NULL,
    Charged_Amount DECIMAL(8,2) NOT NULL DEFAULT 0.00,
    Amount_Saved   DECIMAL(8,2) NOT NULL DEFAULT 0.00,
    Access_Mode    VARCHAR(50),
    FOREIGN KEY (Member_ID)      REFERENCES Member(Member_ID),
    FOREIGN KEY (Item_ID)        REFERENCES Digital_Item(Item_ID),
    FOREIGN KEY (Access_Type_ID) REFERENCES Access_Type(Access_Type_ID)
);
GO

-- 11. Guest_Access
--     Tracks which guest accessed which public item
CREATE TABLE Guest_Access (
    Guest_Access_ID INT         PRIMARY KEY,
    Guest_ID        INT         NOT NULL,
    Item_ID         INT         NOT NULL,
    Access_Date     DATE        NOT NULL,
    Access_Mode     VARCHAR(50),
    FOREIGN KEY (Guest_ID) REFERENCES Guest(Guest_ID),
    FOREIGN KEY (Item_ID)  REFERENCES Digital_Item(Item_ID)
);
GO

