-- ============================================================
-- SAMPLE QUERIES (All 5 required queries from requirement)
-- ============================================================

-- --------------------------------------------------------
-- Query 1: Search library by keyword/phrase
-- --------------------------------------------------------
SELECT DI.Item_ID, DI.Title, IT.Type_Name, AT.Access_Name, DI.Publish_Date
FROM Digital_Item DI
JOIN Item_Type   IT ON DI.Item_Type_ID   = IT.Item_Type_ID
JOIN Access_Type AT ON DI.Access_Type_ID = AT.Access_Type_ID
WHERE DI.Title LIKE '%Physics%';
GO

-- --------------------------------------------------------
-- Query 2: Number of accesses to an item in a date range
-- --------------------------------------------------------
SELECT DI.Title, COUNT(*) AS Total_Accesses
FROM Access_Record AR
JOIN Digital_Item DI ON AR.Item_ID = DI.Item_ID
WHERE AR.Item_ID = 1
  AND AR.Access_Date BETWEEN '2022-01-01' AND '2022-12-31'
GROUP BY DI.Title;
GO

-- --------------------------------------------------------
-- Query 3: Paid access to a category and revenue earned
-- --------------------------------------------------------
SELECT C.Category_Name,
       COUNT(AR.Access_ID)        AS Total_Paid_Access,
       SUM(AR.Charged_Amount)     AS Total_Revenue
FROM Access_Record AR
JOIN Item_Category IC ON AR.Item_ID     = IC.Item_ID
JOIN Category C       ON IC.Category_ID = C.Category_ID
WHERE AR.Charged_Amount > 0
GROUP BY C.Category_Name
ORDER BY Total_Revenue DESC;
GO

-- --------------------------------------------------------
-- Query 4: Member savings (charged paid vs money saved)
-- --------------------------------------------------------
SELECT M.Name,
       MS.Membership_Name,
       SUM(AR.Charged_Amount) AS Total_Paid,
       SUM(AR.Amount_Saved)   AS Total_Saved,
       SUM(AR.Charged_Amount) + SUM(AR.Amount_Saved) AS Full_Price_Would_Have_Paid
FROM Access_Record AR
JOIN Member     M  ON AR.Member_ID     = M.Member_ID
JOIN Membership MS ON M.Membership_ID  = MS.Membership_ID
WHERE AR.Charged_Amount > 0
GROUP BY M.Name, MS.Membership_Name
ORDER BY Total_Saved DESC;
GO

-- --------------------------------------------------------
-- Query 5: Full details of a digital item
-- --------------------------------------------------------
SELECT DI.Item_ID,
       DI.Title,
       IT.Type_Name,
       AT.Access_Name,
       AT.Is_Public,
       AT.Is_Chargeable,
       AT.Download_Allowed,
       AT.View_Only,
       DI.Publish_Date,
       DI.Description,
       C.Category_Name
FROM Digital_Item DI
JOIN Item_Type    IT ON DI.Item_Type_ID   = IT.Item_Type_ID
JOIN Access_Type  AT ON DI.Access_Type_ID = AT.Access_Type_ID
JOIN Item_Category IC ON DI.Item_ID       = IC.Item_ID
JOIN Category      C  ON IC.Category_ID   = C.Category_ID
WHERE DI.Item_ID = 1;
GO

